int _peer_select_version_window(const unsigned char* report, size_t len) {
    if (!report || len < 2) {
        return -1;
    }

    uint8_t version = report[0];
    uint8_t state = report[1];
    (void)version;
    if (state == TASK_STATUS_FAILED) {
        return -1;
    }
    return 0;
}

